using System;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using Codice.Characters;
public static class BuildSoulsCharacters{
 static GameObject go;static Animator rig;static string dir;static int serial;static Material steel,edge,cloth,leather,mail,shadow;static PlayerClass role;
 const string root="Assets/Resources/Presentation/Classes";
 static Transform Bone(HumanBodyBones b)=>rig.GetBoneTransform(b);static Vector3 P(HumanBodyBones b)=>Bone(b).position;
 static Material Material(string name,Color color,float metallic=0,float gloss=.2f){var path=dir+"/"+name+".mat";var m=AssetDatabase.LoadAssetAtPath<Material>(path);if(!m){m=new Material(Shader.Find("Universal Render Pipeline/Lit"));AssetDatabase.CreateAsset(m,path);}m.SetColor("_BaseColor",color);m.SetFloat("_Metallic",metallic);m.SetFloat("_Smoothness",gloss);m.SetFloat("_Cull",0);EditorUtility.SetDirty(m);return m;}
 static Mesh Save(Mesh m,string name){m.name=name;var path=dir+"/"+name+".asset";var old=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(old){old.Clear();old.vertices=m.vertices;old.triangles=m.triangles;old.uv=m.uv;old.boneWeights=m.boneWeights;old.bindposes=m.bindposes;old.RecalculateNormals();old.RecalculateBounds();old.UploadMeshData(false);EditorUtility.SetDirty(old);UnityEngine.Object.DestroyImmediate(m);return old;}AssetDatabase.CreateAsset(m,path);return m;}
 static void Surface(string name,Vector3[] vertices,int[] triangles,Material mat,HumanBodyBones bone,HumanBodyBones? lower=null){var mesh=new Mesh();mesh.vertices=vertices;mesh.triangles=triangles;mesh.uv=vertices.Select(v=>new Vector2(v.x*3+v.z,v.y*3)).ToArray();mesh.RecalculateNormals();mesh.RecalculateBounds();var obj=new GameObject(name);obj.transform.SetParent(go.transform,false);
 if(lower.HasValue){var bones=new[]{Bone(bone),Bone(lower.Value)};var weights=vertices.Select(v=>{float w=Mathf.InverseLerp(bones[1].position.y,bones[0].position.y,v.y);return new BoneWeight{boneIndex0=0,weight0=w,boneIndex1=1,weight1=1-w};}).ToArray();mesh.boneWeights=weights;mesh.bindposes=bones.Select(b=>b.worldToLocalMatrix*obj.transform.localToWorldMatrix).ToArray();var skin=obj.AddComponent<SkinnedMeshRenderer>();skin.sharedMesh=Save(mesh,name);skin.bones=bones;skin.rootBone=Bone(HumanBodyBones.Hips);skin.sharedMaterial=mat;skin.localBounds=new Bounds(Vector3.up,Vector3.one*4);}
 else{obj.AddComponent<MeshFilter>().sharedMesh=Save(mesh,name);obj.AddComponent<MeshRenderer>().sharedMaterial=mat;obj.transform.SetParent(Bone(bone),true);}}
 static void Tube(string name,HumanBodyBones bone,Vector3 a,Vector3 b,float[] radii,float depth,Material mat,int sides=32,float folds=0,HumanBodyBones? lower=null,float start=0,float sweep=6.283185f){Vector3 axis=(b-a).normalized,u=Vector3.Cross(axis,Vector3.forward).normalized;if(u.sqrMagnitude<.1f)u=Vector3.right;Vector3 v=Vector3.Cross(u,axis).normalized;var verts=new List<Vector3>();var tris=new List<int>();for(int j=0;j<radii.Length;j++)for(int i=0;i<=sides;i++){float theta=start+sweep*i/sides;float r=radii[j]*(1+folds*Mathf.Cos(theta*12+j*.3f));verts.Add(Vector3.Lerp(a,b,(float)j/(radii.Length-1))+u*Mathf.Cos(theta)*r+v*Mathf.Sin(theta)*r*depth);}for(int j=0;j<radii.Length-1;j++)for(int i=0;i<sides;i++){int p=j*(sides+1)+i;tris.AddRange(new[]{p,p+sides+2,p+1,p,p+sides+1,p+sides+2});}Surface(name,verts.ToArray(),tris.ToArray(),mat,bone,lower);}
 static void Orb(string name,HumanBodyBones bone,Vector3 center,Vector3 scale,Material mat){var vertices=new List<Vector3>();var tris=new List<int>();int rows=12,cols=24;for(int j=0;j<=rows;j++)for(int i=0;i<=cols;i++){float a=Mathf.PI*j/rows,b=Mathf.PI*2*i/cols;vertices.Add(center+Vector3.Scale(new Vector3(Mathf.Sin(a)*Mathf.Cos(b),Mathf.Cos(a),Mathf.Sin(a)*Mathf.Sin(b)),scale));}for(int j=0;j<rows;j++)for(int i=0;i<cols;i++){int p=j*(cols+1)+i;tris.AddRange(new[]{p,p+cols+2,p+1,p,p+cols+1,p+cols+2});}Surface(name,vertices.ToArray(),tris.ToArray(),mat,bone);}
 static void Ribbon(string name,HumanBodyBones bone,Vector3[] line,float width,Material mat){var v=new List<Vector3>();var tri=new List<int>();for(int i=0;i<line.Length;i++){var tangent=line[Mathf.Min(i+1,line.Length-1)]-line[Mathf.Max(0,i-1)];var perpendicular=Vector3.Cross(tangent,Vector3.forward).normalized*width*.5f;v.Add(line[i]-perpendicular);v.Add(line[i]+perpendicular);if(i>0){int n=i*2;tri.AddRange(new[]{n-2,n,n+1,n-2,n+1,n-1});}}Surface(name,v.ToArray(),tri.ToArray(),mat,bone);}
 static void Rivet(HumanBodyBones bone,Vector3 p,float size=.008f)=>Orb("Remache_"+(serial++),bone,p,Vector3.one*size,edge);
 static void ClothPanel(string name,HumanBodyBones thigh,float x,float yTop,float length,float width,float z,Material material){var vertices=new List<Vector3>();var tris=new List<int>();for(int j=0;j<=14;j++)for(int i=0;i<=12;i++){float t=j/14f,u=i/12f;float xx=x+(u-.5f)*width*(1+t*.5f);float yy=yTop-length*t+(j==14?.025f*Mathf.Sin(i*2.3f):0);float zz=z+Mathf.Sin(u*Mathf.PI*6)*.012f*t+t*t*.07f;vertices.Add(new Vector3(xx,yy,zz));if(j>0&&i>0){int k=j*13+i;tris.AddRange(new[]{k,k-1,k-14,k,k-14,k-13});}}Surface(name,vertices.ToArray(),tris.ToArray(),material,HumanBodyBones.Hips,thigh);}
 static void Gloves(){var r=go.GetComponentsInChildren<SkinnedMeshRenderer>().First();var mesh=UnityEngine.Object.Instantiate(r.sharedMesh);var weights=mesh.boneWeights;bool IsHand(int bone){var t=r.bones[bone];return t.IsChildOf(Bone(HumanBodyBones.LeftHand))||t.IsChildOf(Bone(HumanBodyBones.RightHand));}bool Keep(int i){var w=weights[i];return (IsHand(w.boneIndex0)?w.weight0:0)+(IsHand(w.boneIndex1)?w.weight1:0)+(IsHand(w.boneIndex2)?w.weight2:0)+(IsHand(w.boneIndex3)?w.weight3:0)>.6f;}var triangles=mesh.triangles;var filtered=new List<int>();for(int i=0;i<triangles.Length;i+=3)if(Keep(triangles[i])&&Keep(triangles[i+1])&&Keep(triangles[i+2]))filtered.AddRange(new[]{triangles[i],triangles[i+1],triangles[i+2]});mesh.subMeshCount=1;mesh.triangles=filtered.ToArray();r.sharedMesh=Save(mesh,"Guantes articulados");r.sharedMaterials=new[]{leather};}
 public static string Run(){foreach(PlayerClass kind in Enum.GetValues(typeof(PlayerClass))){role=kind;serial=0;dir=root+"/"+role+"/SoulsV2";System.IO.Directory.CreateDirectory(dir);AssetDatabase.Refresh();go=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Resources/Presentation/Human/HumanPlayer.prefab"));go.name=role+" - Cinders v2";rig=go.GetComponentInChildren<Animator>();rig.enabled=false;
 Color tint=role switch{PlayerClass.Warrior=>new Color(.22f,.045f,.035f),PlayerClass.Tank=>new Color(.085f,.12f,.115f),PlayerClass.Archer=>new Color(.10f,.14f,.085f),PlayerClass.Mage=>new Color(.085f,.08f,.16f),PlayerClass.Shinobi=>new Color(.055f,.065f,.075f),_=>new Color(.24f,.075f,.035f)};
 steel=Material("Acero pavonado",new Color(.16f,.17f,.18f),.75f,.27f);edge=Material("Bronce gastado",new Color(.38f,.29f,.15f),.72f,.36f);cloth=Material("Tejido",tint);leather=Material("Cuero",new Color(.07f,.045f,.032f),0,.22f);mail=Material("Cota de malla",new Color(.10f,.12f,.13f),.6f,.28f);shadow=Material("Sombra",new Color(.012f,.015f,.018f));Gloves();
 bool heavy=role==PlayerClass.Warrior||role==PlayerClass.Tank;float bulk=role==PlayerClass.Tank?1.16f:1;
 Tube("Gambeson",HumanBodyBones.Chest,new Vector3(0,.93f,.02f),new Vector3(0,1.46f,.02f),new[]{.17f,.175f,.145f,.17f,.215f,.225f,.17f},.68f,cloth,40,.025f,HumanBodyBones.Hips);
 Tube("Cuello",HumanBodyBones.Neck,P(HumanBodyBones.Neck)-Vector3.up*.09f,P(HumanBodyBones.Head)+Vector3.up*.02f,new[]{.085f,.09f,.085f,.075f},.9f,heavy?mail:cloth,32,.02f);
 if(heavy){Tube("Coraza forjada",HumanBodyBones.Chest,new Vector3(0,1.14f,.025f),new Vector3(0,1.46f,.025f),new[]{.16f,.168f,.205f,.23f,.215f,.17f}.Select(r=>r*bulk).ToArray(),.72f,steel,48);for(int i=0;i<4;i++)Tube("Lama abdominal "+i,HumanBodyBones.Spine,new Vector3(0,1.08f+i*.038f,.02f),new Vector3(0,1.125f+i*.038f,.02f),new[]{.17f,.182f,.18f},.73f,steel);Ribbon("Cresta pectoral",HumanBodyBones.Chest,new[]{new Vector3(0,1.16f,.15f),new Vector3(0,1.32f,.20f),new Vector3(0,1.44f,.17f)},.014f,edge);}
 else{for(int i=0;i<7;i++)Ribbon("Cierre "+i,HumanBodyBones.Chest,new[]{new Vector3(-.022f,1.17f+i*.032f,.155f),new Vector3(.022f,1.17f+i*.032f,.155f)},.009f,edge);}
 Tube("Cinturon",HumanBodyBones.Hips,new Vector3(0,1.04f,.02f),new Vector3(0,1.10f,.02f),new[]{.175f,.177f,.175f},.75f,leather);Orb("Hebilla",HumanBodyBones.Hips,new Vector3(0,1.07f,.158f),new Vector3(.030f,.022f,.006f),edge);
 // Shoulder harness, articulated sleeves and overlapping plate lames.
 foreach(bool left in new[]{true,false}){string side=left?"I":"D";float sign=left?-1:1;var arm=left?HumanBodyBones.LeftUpperArm:HumanBodyBones.RightUpperArm;var fore=left?HumanBodyBones.LeftLowerArm:HumanBodyBones.RightLowerArm;var hand=left?HumanBodyBones.LeftHand:HumanBodyBones.RightHand;var thigh=left?HumanBodyBones.LeftUpperLeg:HumanBodyBones.RightUpperLeg;var shin=left?HumanBodyBones.LeftLowerLeg:HumanBodyBones.RightLowerLeg;var foot=left?HumanBodyBones.LeftFoot:HumanBodyBones.RightFoot;
 Tube("Manga "+side,arm,P(arm)-Vector3.right*sign*.035f,Vector3.Lerp(P(arm),P(fore),.98f),new[]{.095f,.10f,.092f,.078f,.067f},.9f,heavy?mail:cloth,32,.035f);Orb("Codo "+side,fore,P(fore),new Vector3(.067f,.067f,.067f),heavy?mail:cloth);Tube("Antebrazo "+side,fore,P(fore),P(hand),new[]{.067f,.078f,.071f,.054f,.043f},.9f,heavy?steel:leather);
 for(int i=0;i<4;i++){var a=Vector3.Lerp(P(fore),P(hand),.15f+i*.2f);Tube("Cincha brazo "+side+i,fore,a,a+(P(hand)-P(fore)).normalized*.015f,new[]{.079f-i*.007f,.080f-i*.007f,.079f-i*.007f},.92f,edge,24);}
 Tube("Pantalon "+side,thigh,P(thigh)+Vector3.up*.07f,P(shin),new[]{.105f,.11f,.105f,.087f,.07f},.92f,heavy?mail:cloth,32,.02f);Orb("Rodilla "+side,shin,P(shin),new Vector3(.069f,.073f,.07f),leather);Tube("Bota alta "+side,shin,P(shin)-Vector3.up*.02f,P(foot),new[]{.072f,.087f,.081f,.06f,.052f},.91f,heavy?steel:leather);Orb("Bota "+side,foot,P(foot)+new Vector3(0,-.035f,.045f),new Vector3(.058f,.055f,.125f),leather);Orb("Puntera "+side,foot,P(foot)+new Vector3(0,-.025f,.125f),new Vector3(.055f,.038f,.065f),heavy?steel:leather);
 if(heavy||role==PlayerClass.Berserker||role==PlayerClass.Shinobi){for(int i=0;i<3;i++){var center=Vector3.Lerp(P(arm),P(fore),.06f+i*.15f)+Vector3.up*.09f;Orb("Hombrera lama "+side+i,arm,center,new Vector3(.10f,.045f-i*.006f,.105f-i*.009f)*bulk,steel);Rivet(arm,center+new Vector3(0,.055f,.09f));}Orb("Rodillera acero "+side,shin,P(shin)+Vector3.forward*.055f,new Vector3(.060f,.080f,.025f),steel);}
 if(role==PlayerClass.Shinobi){for(int i=0;i<5;i++){float y=.96f-i*.054f;Tube("Kusazuri "+side+i,thigh,new Vector3(sign*.10f,y,.015f),new Vector3(sign*.10f,y-.045f,.015f),new[]{.13f,.137f,.14f},.85f,steel,24);}}
 else{float length=role==PlayerClass.Mage?.82f:role==PlayerClass.Archer?.48f:heavy?.40f:.32f;ClothPanel("Faldon delantero "+side,thigh,sign*.105f,1.04f,length,.19f,.145f,cloth);ClothPanel("Faldon trasero "+side,thigh,sign*.105f,1.04f,length,.22f,-.15f,cloth);}
 }
 // Faces stay concealed in an original sallet or stitched hood, never a mannequin head.
 var head=P(HumanBodyBones.Head);
 Orb("Cabeza oculta",HumanBodyBones.Head,head+Vector3.up*.09f,new Vector3(.095f,.14f,.105f),shadow);
 if(heavy||role==PlayerClass.Shinobi){Orb("Calota",HumanBodyBones.Head,head+new Vector3(0,.10f,-.012f),new Vector3(.115f,.155f,.125f),steel);Tube("Visera inferior",HumanBodyBones.Head,head+new Vector3(0,-.025f,.015f),head+new Vector3(0,.115f,.015f),new[]{.08f,.108f,.12f,.125f},1.05f,steel,40);Ribbon("Ranura ocular",HumanBodyBones.Head,new[]{head+new Vector3(-.105f,.12f,.085f),head+new Vector3(-.055f,.12f,.14f),head+new Vector3(.055f,.12f,.14f),head+new Vector3(.105f,.12f,.085f)},.018f,shadow);for(int row=0;row<2;row++)for(int i=-2;i<=2;i++)Orb("Respiradero "+row+" "+i,HumanBodyBones.Head,head+new Vector3(i*.027f,.035f+row*.027f,.14f),new Vector3(.005f,.009f,.003f),shadow);if(role==PlayerClass.Shinobi){Tube("Shikoro",HumanBodyBones.Head,head+Vector3.down*.11f,head+Vector3.up*.04f,new[]{.17f,.165f,.15f,.13f},1.05f,steel,36,0,null,Mathf.PI*.08f,Mathf.PI*.84f);}}
 else{Tube("Capucha tejida",HumanBodyBones.Head,head+Vector3.down*.10f,head+Vector3.up*.28f,new[]{.15f,.16f,.145f,.13f,.105f,.045f,.002f},1,cloth,48,.025f,null,Mathf.PI*.85f,Mathf.PI*1.30f);Tube("Bufanda",HumanBodyBones.Neck,head-Vector3.up*.07f,head+Vector3.up*.025f,new[]{.105f,.12f,.12f,.10f},1,cloth,40,.04f);}
 // Cross-body leather baldric and individual rivets, readable without oversized blocks.
 var strap=new[]{new Vector3(-.17f,1.44f,.185f),new Vector3(-.09f,1.33f,.21f),new Vector3(.01f,1.21f,.205f),new Vector3(.12f,1.09f,.195f)};Ribbon("Bandolera",HumanBodyBones.Chest,strap,.048f,leather);for(int i=0;i<strap.Length;i++)Rivet(HumanBodyBones.Chest,strap[i]+Vector3.forward*.003f);
 if(role==PlayerClass.Archer){var a=new Vector3(.16f,1.10f,-.20f);Tube("Carcaj cuero",HumanBodyBones.Chest,a,a+new Vector3(-.04f,.48f,0),new[]{.045f,.065f,.065f,.075f},1,leather,32);for(int i=0;i<6;i++){var tip=a+new Vector3(-.07f+i*.018f,.65f,0);Tube("Astil "+i,HumanBodyBones.Chest,tip-Vector3.up*.28f,tip,new[]{.005f,.005f},1,edge,8);Ribbon("Pluma "+i,HumanBodyBones.Chest,new[]{tip-Vector3.up*.065f,tip},.028f,cloth);}}
 if(role==PlayerClass.Mage){Tube("Estola",HumanBodyBones.Chest,new Vector3(0,1.39f,0),new Vector3(0,1.48f,0),new[]{.22f,.20f,.12f},.72f,edge,40);for(int i=0;i<9;i++)Orb("Cuentas "+i,HumanBodyBones.Chest,new Vector3((i-4)*.025f,1.34f-Mathf.Sin(i*Mathf.PI/8)*.07f,.175f),Vector3.one*.012f,edge);}
 if(role==PlayerClass.Berserker){for(int i=0;i<20;i++){float t=i*Mathf.PI*2/20;Orb("Piel cuello "+i,HumanBodyBones.Chest,new Vector3(Mathf.Cos(t)*.18f,1.43f+Mathf.Sin(i*3)*.02f,Mathf.Sin(t)*.10f),new Vector3(.045f,.045f,.04f),leather);}}
 rig.enabled=true;rig.runtimeAnimatorController=Resources.Load<RuntimeAnimatorController>(role==PlayerClass.Berserker?"Presentation/Human/Berserker":"Presentation/Human/HumanPlayer");PrefabUtility.SaveAsPrefabAsset(go,root+"/"+role+".prefab");UnityEngine.Object.DestroyImmediate(go);
 }AssetDatabase.SaveAssets();return "Six redesigned characters: shaped armor, articulated cloth, gloves, concealed faces, layered gear";}
